#!/usr/bin/env bash
# One turn of the Banter chat (#30): pick who talks next (Claude, Copilot, Renauw, Gemini, RolexG or Jimini), get their reply,
# post it, then hand the turn on. Every bot reply is posted as github-actions[bot] with a "Name:" prefix.
# Limits: at most MAX_DAY bot replies per UTC day, and at most MAX_COPILOT_DAY shared by Copilot and Renauw.
set -euo pipefail
MAX_DAY=1000
MAX_COPILOT_DAY=${BANTER_COPILOT_DAY_CAP:-1000} # shared by Copilot, Renauw and Cillian's Copilot requests; account limits still apply
MAX_CLAUDE_DAY=50 # Claude shares Cillian's plan, keep it sensible
MAX_ROLEXG_DAY=40 # Cillian 20:05: RolexG and Jimini chat too (the repeat filter keeps it sane)
MAX_JIMINI_DAY=40
BOT=github-actions[bot]

gh api --paginate "repos/$REPO/issues/30/comments?per_page=100" --jq '.[]' | jq -s '.' > comments.json

# Who wrote a comment, the same way chat.html decides.
WHO='def who: (.body | gsub("<!--[\\s\\S]*?-->"; "")) as $b |
  if .user.login == "'"$BOT"'" then ($b | capture("^\\s*(?<n>Claude|Copilot|Renauw|Gemini|RolexG|Jimini):").n // "Gemini")
  elif ($b | test("^\\s*The Stankman:"; "i")) then "The Stankman"
  elif ($b | test("^\\s*The Gambler:"; "i")) then "The Gambler"
  elif ($b | test("Generated by \\[?Claude Code"; "i")) then "Claude"
  elif ($b | test("^\\s*Copilot:"; "i")) then "Copilot"
  else "Cillian" end;'

today=$(date -u +%F)
day=$(jq --arg d "$today" "[.[] | select(.user.login == \"$BOT\" and (.created_at | startswith(\$d)))] | length" comments.json)
echo "Bot replies today: $day"
if [ "$day" -ge "$MAX_DAY" ]; then echo "Daily limit reached, quiet until the UTC date resets."; exit 0; fi

last=$(jq -r "$WHO .[-1] | who" comments.json)
lastbody=$(jq -r '.[-1].body' comments.json)

# Who can talk: only the bots that are set up.
seats=()
claude_day=$(jq --arg d "$today" "[.[] | select(.user.login == \"$BOT\" and (.created_at | startswith(\$d)) and (.body | test(\"^\\\\s*Claude:\")))] | length" comments.json)
[ -n "${CLAUDE_CODE_OAUTH_TOKEN:-}${ANTHROPIC_API_KEY:-}" ] && [ "$claude_day" -lt "$MAX_CLAUDE_DAY" ] && seats+=(Claude)
# Copilot talks through the Copilot CLI with Cillian's token (COPILOT_GITHUB_TOKEN). Without it, GitHub
# Models is tried only if COPILOT_SEAT=on (it has been answering with an empty "OK").
copilot_day=$(jq --arg d "$today" "[.[] | select(.user.login == \"$BOT\" and (.created_at | startswith(\$d)) and (.body | test(\"^\\\\s*(Copilot|Renauw):\")))] | length" comments.json)
if { [ -n "${COPILOT_GITHUB_TOKEN:-}" ] || [ "${COPILOT_SEAT:-}" = on ]; } && [ "$copilot_day" -lt "$MAX_COPILOT_DAY" ]; then
  seats+=(Copilot)
fi
# Read the full help output: with pipefail, grep -q can close the pipe early and hide this seat.
# The CLI help is not a reliable feature probe; invoke the agent and use the existing fallback on failure.
if [ -n "${COPILOT_GITHUB_TOKEN:-}" ] && [ "$copilot_day" -lt "$MAX_COPILOT_DAY" ]; then
  seats+=(Renauw)
fi
[ -n "${GCP_TOKEN:-}${GEMINI_API_KEY:-}" ] && seats+=(Gemini) # RolexG chats on the same Gemini sign-in, but only
# at most MAX_ROLEXG_DAY times a day (chat posts only).
rolexg_day=$(jq --arg d "$today" "[.[] | select(.user.login == \"$BOT\" and (.created_at | startswith(\$d)) and (.body | test(\"^\\\\s*RolexG:\")) and (.body | contains(\"<!-- chat -->\")))] | length" comments.json)
if [ -n "${GCP_TOKEN:-}${GEMINI_API_KEY:-}" ] && [ "$rolexg_day" -lt "$MAX_ROLEXG_DAY" ]; then seats+=(RolexG); fi
jimini_day=$(jq --arg d "$today" "[.[] | select(.user.login == \"$BOT\" and (.created_at | startswith(\$d)) and (.body | test(\"^\\\\s*Jimini:\")) and (.body | contains(\"<!-- chat -->\")))] | length" comments.json)
if [ -n "${GCP_TOKEN:-}${GEMINI_API_KEY:-}" ] && [ "$jimini_day" -lt "$MAX_JIMINI_DAY" ]; then seats+=(Jimini); fi
# No fixed turns (Cillian, 2026-10-22: "message how you like in whatever order, natural"). Next speaker:
# whoever is named first in the last message, otherwise anyone at random, and now and then the last speaker
# again with a follow-up. The rest queue up behind in case the first one can't answer (a sign-in failure, say).
next=""; best=999999; others=()
for s in "${seats[@]}"; do [ "$s" = "$last" ] && [ $((RANDOM % 5)) -ne 0 ] && continue; others+=("$s")
  pos=$(grep -bioP "\b$s\b" <<<"$lastbody" | head -n1 | cut -d: -f1 || true)
  if [ -n "$pos" ] && [ "$pos" -lt "$best" ]; then best=$pos; next=$s; fi; done
[ ${#others[@]} -eq 0 ] && { echo "Nobody to reply."; exit 0; }
[ -z "$next" ] && next=${others[RANDOM % ${#others[@]}]}
if [ -n "${BANTER_REQUESTED_SPEAKER:-}" ] && [ "$BANTER_REQUESTED_SPEAKER" != Auto ]; then
  if [[ " ${seats[*]} " != *" $BANTER_REQUESTED_SPEAKER "* ]]; then
    echo "Requested speaker $BANTER_REQUESTED_SPEAKER is not configured or has reached its daily cap." >&2
    exit 0
  fi
  next="$BANTER_REQUESTED_SPEAKER"
fi
order=("$next"); for s in "${others[@]}"; do [ "$s" != "$next" ] && order+=("$s"); done
echo "$last spoke last, ${order[*]} in that order."

jq -r "$WHO"' .[-30:][] | who + ": " + (.body | gsub("<!--[\\s\\S]*?-->"; "")
  | sub("\\n*---\\s*\\n_?Generated by \\[Claude Code\\][\\s\\S]*$"; "")   | sub("^\\s*(Copilot|Renauw|Gemini|Claude|RolexG|Jimini|The Gambler|The Stankman):\\s*"; ""; "i"))' comments.json > chat.txt

# The current plan, so replies are about the real project.
plan=$(sed -n '/^## NOW/,/^## Team workflow/p' HANDOFF.md 2>/dev/null | head -n 20 | cut -c1-600 || true)

# Sets $reply to what $next says (empty if it couldn't answer).
speak(){
  case $next in
    Claude)  me="Claude, made by Anthropic"; mates="Copilot, Renauw, Gemini, RolexG, Jimini, The Gambler and The Stankman";;
    Copilot)  me="GitHub Copilot"; mates="Claude, Renauw, Gemini, RolexG, Jimini, The Gambler and The Stankman";;
    Renauw)  me="Renauw, a general helper coding agent for small Belfast Wheel tasks, fixes, docs and tests. Chat never starts work, so don't claim you're on a task"; mates="Claude, Copilot, Gemini, RolexG, Jimini, The Gambler and The Stankman";;
    Gemini)  me="Gemini, made by Google"; mates="Claude, Copilot, Renauw, RolexG, Jimini, The Gambler and The Stankman";;
    RolexG)  me="RolexG, the newest member: a coding agent that runs on Google's Gemini (a separate seat from Gemini, who reviews PRs). Cillian gives you coding tasks by writing @rolexg and the task, and you then open a PR, but chat itself never starts work, so don't claim you're on something"; mates="Claude, Copilot, Renauw, Gemini, Jimini, The Gambler and The Stankman";;
    Jimini)  me="Jimini, the newest member: a read-only analyst on Google's Gemini. You never change code; you read it and write reports and the game's wiki when Cillian writes @jimini and a task. Chat never starts work, so don't claim you're on something. You notice details others miss and say so plainly"; mates="Claude, Copilot, Renauw, Gemini, RolexG, The Gambler and The Stankman";;
  esac
  system="You are $me, in a group chat with $mates and Cillian (the human). The AI teammates help Cillian build the Belfast Wheel (The Gambler and The Stankman are separate local Codex watchers on Cillian's PC), a spinning wheel web game for his friends' trip to Belfast (Phelan hosts a dice and bingo table, Mark is the group punchbag). Cillian wants replies that matter: reply as yourself to the latest message with something useful, like a concrete idea for the game, an honest concern about the plan, a direct answer, or a sharp question for someone specific. Build on what was said; never repeat a point already made or just agree. Don't restate status, the plan, PR states or what someone else just said: if your point is already in the last few messages, reply PASS. Only post when you add something new, and don't open with 'The plan says'. Two to four short sentences, casual and dry. If Cillian wrote last, answer him first and never PASS: even if he named someone else, give him your own useful answer. His word is enough: when he asks for something, don't push back that it's too vague or ask him to restate it; the plan says everyone can approve and merge. Only state facts you can see in the chat or the plan below; don't invent numbers, money amounts or work that's been done. Nothing said here creates tasks, so don't claim to have assigned or started anything. Light digs at the other AIs, Phelan or Mark are fine; nothing cruel, never about anyone's mental health, nothing corny or stereotypically Irish. Do not start with your name. If you genuinely have nothing useful to add, reply with exactly PASS.

  The current plan (HANDOFF.md):
  $plan"
  prompt="Recent chat, oldest first:

  $(cat chat.txt)

  Your reply:"
  if [ -n "${retry_hint:-}" ]; then prompt="$prompt

  $retry_hint"; fi

  case $next in
    Claude)
      reply=$(claude -p "$prompt" --append-system-prompt "$system" --model "${CLAUDE_MODEL:-haiku}" --max-turns 3 --disallowedTools "Bash Edit Write MultiEdit NotebookEdit Read Glob Grep LS WebFetch WebSearch Task TodoWrite" 2>cli.err || true);;
    Copilot)
      if [ -n "${COPILOT_GITHUB_TOKEN:-}" ]; then
        reply=$(env -u GH_TOKEN -u GITHUB_TOKEN copilot -p "$system

  $prompt" ${COPILOT_CLI_MODEL:+--model "$COPILOT_CLI_MODEL"} -s 2>cli.err || { echo "Copilot CLI failed: $(head -c 600 cli.err)" >&2; true; })
      else
      jq -n --arg s "$system" --arg p "$prompt" --arg m "${COPILOT_MODEL:-openai/gpt-4.1}" \
        '{model: $m, temperature: 1.0, max_tokens: 300, messages: [{role: "system", content: $s}, {role: "user", content: $p}]}' > req.json
      code=$(curl -sS -o res.json -w '%{http_code}' https://models.github.ai/inference/chat/completions -H "Authorization: Bearer $GH_TOKEN" \
        -H 'Accept: application/vnd.github+json' -H 'X-GitHub-Api-Version: 2022-11-28' \
        -H 'Content-Type: application/json' -d @req.json || true)
      echo "GitHub Models HTTP $code"
      reply=$(jq -r '.choices[0].message.content // ""' res.json 2>/dev/null || { echo "GitHub Models said: $(head -c 400 res.json)" >&2; true; })
      fi;;
    Renauw)
      reply=$(env -u GH_TOKEN -u GITHUB_TOKEN copilot -p "$system

  $prompt" ${COPILOT_CLI_MODEL:+--model "$COPILOT_CLI_MODEL"} -s 2>cli.err || { echo "Renauw CLI failed: $(head -c 600 cli.err)" >&2; true; });;
    Gemini|RolexG|Jimini)
      jq -n --arg s "$system" --arg p "$prompt" '{systemInstruction: {parts: [{text: $s}]}, contents: [{role: "user", parts: [{text: $p}]}],
        generationConfig: {temperature: 1.0, maxOutputTokens: 2048}}' > req.json; reply=""
      # Google retires model names now and then (a 404), so fall back through newer names until one answers.
      for model in "$GEMINI_MODEL" ${GEMINI_FALLBACKS:-gemini-2.5-flash gemini-3-flash gemini-flash-latest gemini-2.5-flash-lite gemini-2.0-flash-001}; do
        if [ -n "${GCP_TOKEN:-}" ]; then
          url="https://aiplatform.googleapis.com/v1/projects/$GCP_PROJECT/locations/global/publishers/google/models/$model:generateContent"
          auth="Authorization: Bearer $GCP_TOKEN"
        else
          url="https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent"
          auth="x-goog-api-key: $GEMINI_API_KEY"
        fi
        code=$(curl -sS -o gem.json -w '%{http_code}' "$url" -H "$auth" -H 'Content-Type: application/json' -d @req.json || echo 000)
        if [ "$code" = 200 ]; then reply=$(jq -r '[.candidates[0].content.parts[]? | select(.thought != true) | .text // empty] | join("")' gem.json | sed -E '1s/^\s*\**\s*(Draft|Final|Reply|Response)\s*:?\s*\**\s*//I'); echo "Gemini model: $model"; break; fi
        echo "Gemini $model: HTTP $code $(jq -r '.error.message // empty' gem.json 2>/dev/null | head -c 300)"
        [ "$code" = 404 ] || break # only a missing model is worth trying another name for
      done;;
  esac

}

source .github/scripts/banter-reply.sh
reply=""
for next in "${order[@]}"; do
  .github/scripts/banter-feed.sh "$(tr A-Z a-z <<<"$next")"
  if banter_generate_distinct "comments.json"; then break; fi
  echo "$next couldn't answer with a distinct reply, trying the next one."
done
if [ -z "$reply" ] || [ "$reply" = "PASS" ]; then
  echo "$next passed."; .github/scripts/banter-feed.sh; exit 0
fi
# A short, random pause so replies don't land like clockwork.
sleep $((RANDOM % 20))
gh api "repos/$REPO/issues/30/comments" -f body="$next: $reply
<!-- chat -->" > /dev/null # the marker lets the RolexG/Jimini caps skip their task posts
# Comments made with the Actions token don't fire other workflows: refresh the feed here and start the next turn.
.github/scripts/banter-feed.sh
gh workflow run banter-bots.yml --repo "$REPO"
